css:
/* Handoff .hero: 88px band, the branch banner under a 72% chrome scrim, centred copy in a 960px well. */
[data-bz-section="location-hero"] > .bz-section { position: relative; overflow: hidden; padding-block: 88px; padding-inline: var(--container-pad); background: var(--chrome); color: #fff; text-align: center }
[data-bz-section="location-hero"] [data-bz-node^="lh-banner"] { position: absolute; inset: 0; z-index: 0; margin: 0; padding: 0 }
[data-bz-section="location-hero"] [data-bz-node^="lh-banner"] :is(.bz-container, .bz-image, figure, picture) { height: 100%; margin: 0; max-width: none }
[data-bz-section="location-hero"] [data-bz-node^="lh-banner"] img { width: 100%; height: 100%; object-fit: cover; border-radius: 0 }
[data-bz-section="location-hero"] .bz-photo--empty { display: none }
[data-bz-section="location-hero"] > .bz-section::after { content: ""; position: absolute; inset: 0; background: color-mix(in srgb, var(--chrome) 72%, transparent); z-index: 1; pointer-events: none }
/* The banner is sized to the band, so nothing between it and the section may be positioned. */
[data-bz-section="location-hero"] > .bz-section > .bz-container,
[data-bz-section="location-hero"] .bz-row,
[data-bz-section="location-hero"] [data-bz-node^="lh-col"] { position: static }
[data-bz-section="location-hero"] [data-bz-node^="lh-col"] { max-width: 960px; margin-inline: auto; width: 100% }
[data-bz-section="location-hero"] [data-bz-node^="lh-col"] > .bz-block:not([data-bz-node^="lh-banner"]) { position: relative; z-index: 2 }
[data-bz-section="location-hero"] h1 { color: #fff; font-size: 44px; line-height: 1.14; letter-spacing: -0.01em; margin: 0 0 22px }
[data-bz-section="location-hero"] [data-bz-node^="lh-crumb"] p { font: 700 11px / 1 var(--font-body); letter-spacing: .16em; text-transform: uppercase; color: #E2E2E2; margin: 0 0 22px }
[data-bz-section="location-hero"] [data-bz-node^="lh-crumb"] a { color: #E2E2E2; text-decoration: none }
[data-bz-section="location-hero"] [data-bz-node^="lh-crumb"] a:hover { text-decoration: underline }
[data-bz-section="location-hero"] [data-bz-node^="lh-sub"] p { color: #E2E2E2; font-size: 17px; line-height: 1.7; max-width: 700px; margin: 0 auto 30px }
[data-bz-section="location-hero"] .bz-btns { justify-content: center; gap: 14px; margin-block: 0 }
/* Handoff .btn: 48px, rounded 8px like the header phone CTA, sentence case, 14px text at 700. The design system has no red, so a filled
   button on the dark band takes the highlight the header phone button uses. */
[data-bz-section="location-hero"] .bz-btn { min-height: 48px; padding: 0 26px; border-radius: 8px; font: 700 14px / 1.2 var(--font-body); letter-spacing: 0; text-transform: none }
[data-bz-section="location-hero"] .bz-btn--primary { background: var(--accent-dark); color: #fff; border: 1px solid transparent }
[data-bz-section="location-hero"] .bz-btn--primary:hover { background: var(--accent-dark); filter: brightness(.9) }
[data-bz-section="location-hero"] .bz-btn--secondary { background: transparent; color: #fff; border: 1px solid #fff }
[data-bz-section="location-hero"] .bz-btn--secondary:hover { background: #fff; color: var(--chrome) }
@media (max-width: 1100px) { [data-bz-section="location-hero"] > .bz-section { padding-inline: var(--container-pad-tablet) } }
@media (max-width: 640px) {
  [data-bz-section="location-hero"] > .bz-section { padding-block: 72px; padding-inline: var(--container-pad-mobile) }
  [data-bz-section="location-hero"] h1 { font-size: 30px }
}
